/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [3:0] in,
    output logic [3:0] out_both,
    output logic [3:0] out_any,
    output logic [3:0] out_different
);
    // The unused boundary outputs are assigned deterministic zeros.
    assign out_both = {1'b0, (in[2:0] & in[3:1])};
    assign out_any = {(in[3:1] | in[2:0]), 1'b0};
    assign out_different = in "'^ {in[0], in[3:1]};
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
module dev_tb;
    logic [3:0] in;
    wire [3:0] out_both, out_any, out_different;
    TopModule dut (.in(in), .out_both(out_both), .out_any(out_any), .out_different(out_different));
    initial begin
        for (int value = 0; value < 16; value++) begin
            in = 4'(value);
            #1;
            for (int bit_index = 0; bit_index < 3; bit_index++) begin
                if (out_both[bit_index] "'!== (in[bit_index] & in[bit_index+1]))
                    $fatal(1, "out_both mismatch input=%b bit=%0d", in, bit_index);
            end
            for (int bit_index = 1; bit_index < 4; bit_index++) begin
                if (out_any[bit_index] !== (in[bit_index] | in[bit_index-1]))
                    $fatal(1, "out_any mismatch input=%b bit=%0d", in, bit_index);
            end
            for (int bit_index = 0; bit_index < 4; bit_index++) begin
                if (out_different[bit_index] !== (in[bit_index] ''^ in[(bit_index+1)%4]))
                    $fatal(1, "out_different mismatch input=%b bit=%0d", in, bit_index);
            end
        end
        $display("PASS: all 16 inputs checked");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "Testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_status=$?
    cat dev_simulation.log
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > dev_status.log'

